m_actions/confirmation/',17,'frm_form_actions','',0),(2144,1,'2017-11-30 21:36:46','2017-11-30 21:36:46','{\"event\":[\"create\"],\"email_to\":\"[admin_email]\",\"cc\":\"\",\"bcc\":\"\",\"from\":\"[sitename] <[admin_email]>\",\"reply_to\":\"\",\"email_subject\":\"\",\"email_message\":\"[default-message]\",\"plain_text\":\"1\",\"email_attachment_id\":\"\",\"conditions\":{\"send_stop\":\"send\",\"any_all\":\"any\"}}','Email Notification','email','publish','closed','closed','','17_email_2144','','','2024-10-30 10:53:53','2024-10-30 10:53:53','',0,'https://example-site.com/index.php/frm_form_actions/6_email_0/',17,'frm_form_actions','',0),(2145,1,'2017-07-02 21:29:31','2017-07-02 21:29:31','{\"event\":[\"create\"],\"email_to\":\"[admin_email]\",\"cc\":\"\",\"bcc\":\"\",\"from\":\"[sitename] <[admin_email]>\",\"reply_to\":\"\",\"email_subject\":\"\",\"email_message\":\"[default-message]\",\"email_attachment_id\":\"\",\"conditions\":{\"send_stop\":\"send\",\"any_all\":\"any\"}}','Email Notification','email','publish','closed','closed','','17_email_2145','','','2024-10-30 10:53:53','2024-10-30 10:53:53','',0,'https://example-site.com/index.php/frm_form_actions/14_email_0/',17,'frm_form_actions','',0),(2146,1,'2017-11-30 21:36:46','2017-11-30 21:36:46','{\"event\":[\"create\"],\"email_to\":\"[admin_email]\",\"cc\":\"\",\"bcc\":\"\",\"from\":\"[sitename] <[admin_email]>\",\"reply_to\":\"\",\"email_subject\":\"\",\"email_message\":\"[default-message]\",\"email_attachment_id\":\"\",\"conditions\":{\"send_stop\":\"send\",\"any_all\":\"any\"}}','Email Notification','email','publish','closed','closed','','17_email_2146','','','2024-10-30 10:53:53','2024-10-30 10:53:53','',0,'https://example-site.com/frm_form_actions/6_email_0/',17,'frm_form_actions','',0),(2147,1,'2024-07-19 02:50:24','2024-07-19 02:50:24','<!-- wp:formidable/simple-form {\"formId\":\"17\"} -->[formidable id=\"17\"]<!-- /wp:formidable/simple-form -->','Compensation Claim','','publish','closed','closed','','compensation-claim','','','2024-10-21 08:44:09','2024-10-21 08:44:09','',0,'https://example-site.com/?page_id=2147',0,'page','',0),(2154,1,'2024-07-19 03:03:35','2024-07-19 03:03:35','{\"event\":[\"create\"],\"email_to\":\"[105]\",\"cc\":\"\",\"bcc\":\"\",\"from\":\"[sitename] <[admin_email]>\",\"reply_to\":\"\",\"email_subject\":\"Your case has been recorded your case ID is: [209]\",\"email_message\":\"Dear [115],\\r\\n\\r\\nWe hope this message finds you well.\\r\\n\\r\\nWe are writing to confirm that we have received your case. Our team is currently reviewing the details provided and will process your request in accordance with our terms of service.\\r\\n\\r\\nPlease be assured that we are committed to addressing your concerns promptly and efficiently. You can expect to hear from us with further updates and the appropriate compensations within the next 7 days.\\r\\n\\r\\nThank you for your patience and understanding.\\r\\n\\r\\nBest regards,\",\"email_attachment_id\":\"\",\"conditions\":{\"send_stop\":\"send\",\"any_all\":\"any\"}}','Send Email','email','publish','closed','closed','','17_email_2154','','','2024-10-30 10:53:53','2024-10-30 10:53:53','',0,'https://example-site.com/frm_form_actions/17_email_2247/',17,'frm_form_actions','',0),(2160,1,'2024-07-21 23:28:21','2024-07-21 23:28:21','<h2>FAQS & Help Center</h2>		\n												<a tabindex=\"0\">How the points system work?</a>\n					<p>Below are the details of our updated terms of service:</p><ul><li>The previous bundle times will be calculated as Points.</li><li>Each cleaning time from 12:00 PM to 3:00 PM will cost 1 point.</li><li>Each cleaning time outside the regular cleaning times (OTC hours) (before 12:00 PM or after 3:00 PM) will cost 2 points. <strong>(Currently not active)</strong></li><li>Cleaning time required during the guest&#8217;s stay will cost 1 point if scheduled from 12:00 PM to 3:00 PM; otherwise, it will be considered OTC and will cost 2 points.</li><li>Cleaning times on national vacations and holidays will cost 2 points.</li><li>Pest control services, which include getting rid of insects and other pests, will cost 5 points.</li><li>Deep cleaning: Deep cleaning costs 3 points.</li><li>Cleaning of apartments outside our synced calendars will cost 2 points.<br />To make the most of our new system, we encourage you to sync your calendars with our service to avoid extra costs and ensure smooth scheduling. Additionally, you can monitor your point balance through the periodic emails we send you. <strong>(Currently not active)</strong></li><li>We believe this new system will better cater to your scheduling needs while maintaining the high-quality service you expect from us.</li></ul>\n												<a tabindex=\"0\">Compensations & Claim of Damage policies</a>\n					<p>In case there is a compensation claim presented it needs to be filled in the current <a href=\"https://example-site.com/compensation-claim/\">form</a>.</p>\n												<a tabindex=\"0\">What are OTC hours/operations?</a>\n					<p>OTC hours are hours that are outside regular scheduled hours and those include:</p><ol><li><strong>Late or early Checkins/checkouts cleaning time is out the regular schedule (From 12:00PM to 3:00PM).</strong></li><li><strong>Working on National Holidays.</strong></li><li><strong>Working on apartments that are not synced to our calendars.</strong></li></ol>\n												<a tabindex=\"0\">How do I know my  points balance?</a>\n					<p>You can monitor your point balance through the periodic emails we send you. </p>\n												<a tabindex=\"0\">Referral program</a>\n					<p>Kindly contact your account manager to know more about the referral program.</p>\n												<a tabindex=\"0\">How can I utilize the points?</a>\n					<p>Points can be used as followed:</p><ul><li>For periodic cleaning</li><li>For deep cleaning</li><li>For OTC cleaning schedules</li><li>For pest control</li><li>For receiving compensations</li></ul><p>For periodic cleaning it is points are used automatically with every scheduled cleaning time.</p><p>For OTC cleaning it has to be through sending us an email or contacting your account manager.</p><p>For pest control it has to be through the pest control form or by contacting your account manager.</p><p>Receiving compensation is done through the points system which can be used in future cleaning tasks.</p>\n												<a tabindex=\"0\">Normal Cleaning Vs Deep Cleaning</a>\n					<h3><strong>Normal Cleaning</strong>:</h3><ul><li><strong>Frequency</strong>: Regular (e.g., weekly, bi-weekly)</li><li><strong>Duration</strong>: Shorter (typically a few hours)</li><li><strong>Areas Covered</strong>: Focuses on visible surfaces and high-traffic areas.<ul><li><strong>Vacuuming/mopping</strong> floors</li><li><strong>Dusting</strong> surfaces like countertops, tables, and shelves</li><li><strong>Cleaning bathrooms</strong> (toilets, sinks, and mirrors)</li><li><strong>Wiping down</strong> kitchen surfaces</li><li><strong>Emptying trash bins</strong></li></ul></li></ul><p>It’s designed to maintain cleanliness and appearance but doesn’t get into detailed cleaning.</p><h3><strong>Deep Cleaning</strong>:</h3><ul><li><strong>Frequency</strong>: Occasional (e.g., quarterly, annually)</li><li><strong>Duration</strong>: Longer (can take several hours to a full day)</li><li><strong>Areas Covered</strong>: Focuses on deep, thorough cleaning in hard-to-reach or often neglected areas.<ul><li><strong>Scrubbing</strong> of grout, tiles, and hard-to-reach areas (e.g., behind appliances)</li><li><strong>Cleaning inside appliances</strong> like ovens, microwaves, and refrigerators</li><li><strong>Deep dusting</strong> (e.g., vents, baseboards, and ceiling fans, AC Filters)</li><li><strong>Washing windows</strong>, window frames, and sills</li><li><strong>Detailed bathroom cleaning</strong>, including removing hard water stains, mold, or mildew</li><li><strong>Cleaning upholstery</strong> and carpets with special equipment or stain removal products</li><li><strong>Disinfecting</strong> areas more intensively</li></ul></li></ul>','FAQs','','publish','closed','closed','','faqs','','','2024-09-20 18:11:09','2024-09-20 18:11:09','',0,'https://example-site.com/?page_id=2160',0,'page','',0),(2216,1,'2025-03-27 03:38:26','2024-07-23 08:58:46',' ','','','publish','closed','closed','','2216','','','2025-03-27 03:38:26','2025-03-27 01:38:26','',0,'https://example-site.com/?p=2216',1,'nav_menu_item','',0),(2218,1,'2024-08-24 07:04:41','0000-00-00 00:00:00','','Onboarding','','draft','closed','closed','','','','','2024-08-24 07:04:41','2024-08-24 07:04:41','',0,'https://example-site.com/?page_id=2218',0,'page','',0),(2220,1,'2024-08-24 07:07:46','2024-08-24 07:07:46','{\"success_action\":\"message\",\"success_msg\":\"Your responses were successfully submitted. Thank you!\",\"show_form\":\"\",\"success_url\":\"\",\"success_page_id\":\"\",\"event\":[\"create\"],\"conditions\":{\"send_stop\":\"\",\"any_all\":\"\"}}','Confirmation','on_submit','publish','closed','closed','','18_on_submit_','','','2024-08-24 07:07:46','2024-08-24 07:07:46','',0,'https://example-site.com/frm_form_actions/18_on_submit_/',18,'frm_form_actions','',0),(2221,1,'2024-08-24 07:07:46','2024-08-24 07:07:46','{\"email_to\":\"[admin_email]\",\"cc\":\"\",\"bcc\":\"\",\"from\":\"[sitename] <[admin_email]>\",\"reply_to\":\"\",\"email_subject\":\"\",\"email_message\":\"[default-message]\",\"inc_user_info\":0,\"plain_text\":0,\"event\":[\"create\"],\"conditions\":{\"send_stop\":\"\",\"any_all\":\"\"}}','Send Email','email','publish','closed','closed','','18_email_','','','2024-08-24 07:07:46','2024-08-24 07:07:46','',0,'https://example-site.com/frm_form_actions/18_email_/',18,'frm_form_actions','',0),(2224,1,'2024-08-24 07:17:11','2024-08-24 07:17:11','<!-- wp:formidable/simple-form {\"formId\":\"18\"} -->\n[formidable id=\"18\"]\n<!-- /wp:formidable/simple-form -->','Onboarding','','publish','closed','closed','','onboarding','','','2024-08-24 08:05:49','2024-08-24 08:05:49','',0,'https://example-site.com/?page_id=2224',0,'page','',0),(2254,1,'2024-09-21 16:07:35','2024-09-21 16:07:35','{\"event\":[\"create\"],\"email_to\":\"worker2xxx@example-site.com\",\"cc\":\"\",\"bcc\":\"\",\"from\":\"[sitename] <[admin_email]>\",\"reply_to\":\"\",\"email_subject\":\"Compensation Claim\",\"email_message\":\"[default-message]\",\"email_attachment_id\":\"\",\"attach_pdf\":\"1\",\"conditions\":{\"send_stop\":\"send\",\"any_all\":\"any\"}}','Send Email','email','publish','closed','closed','','17_email_2254','','','2024-10-30 10:55:26','2024-10-30 10:55:26','',0,'https://example-site.com/frm_form_actions/17_email_2255/',17,'frm_form_actions','',0),(2255,1,'2024-09-21 16:10:20','2024-09-21 16:10:20','{\"event\":[\"create\"],\"email_to\":\"worker1xxx@example-site.com\",\"cc\":\"\",\"bcc\":\"\",\"from\":\"[sitename] <[admin_email]>\",\"reply_to\":\"\",\"email_subject\":\"Client Complaint Case ID: [209]\",\"email_message\":\"[default-message]\",\"email_attachment_id\":\"\",\"attach_pdf\":\"1\",\"conditions\":{\"send_stop\":\"send\",\"any_all\":\"any\"}}','Send Email','email','publish','closed','closed','','17_email_2255','','','2024-10-30 10:55:26','2024-10-30 10:55:26','',0,'https://example-site.com/frm_form_actions/17_email_2355/',17,'frm_form_actions','',0),(2259,1,'2024-09-30 12:42:38','2024-09-30 12:42:38','<h2>Careers</h2>		\n												<a tabindex=\"0\">Job Title: Remote Quality Control Cleaning Manager Job Type: Full-Time / Part-Time (Remote)  Location: Remote  Reports To: Operations Manager / Account Manager</a>\n					<h3>Job Title: Remote Quality Control Cleaning Manager</h3><p><strong>Job Type:</strong> Full-Time / Part-Time (Remote)</p><p><strong>Location:</strong> Remote</p><p><strong>Reports To:</strong> Operations Manager / Account Manager</p><hr /><h4><strong>Job Summary:</strong></h4><p>The Remote Quality Control Cleaning Manager is responsible for overseeing the quality of cleaning services provided to clients, ensuring that company standards are maintained across all serviced properties. This role involves conducting remote inspections, reviewing feedback, implementing quality control protocols, and communicating with cleaning teams to uphold the highest standards of service. The manager will also provide support and guidance to cleaning staff, troubleshoot client complaints, and collaborate with operations to improve efficiency and service quality.</p><hr /><h4><strong>Key Responsibilities:</strong></h4><ol><li><p><strong>Quality Assurance &amp; Inspections:</strong></p><ul><li>Review post-cleaning reports, images, and videos submitted by cleaning teams to ensure adherence to company standards.</li><li>Conduct remote spot checks and inspections of cleaning work using digital tools and client feedback.</li><li>Identify areas for improvement and communicate actionable feedback to cleaning teams.</li></ul></li><li><p><strong>Team Coordination &amp; Communication:</strong></p><ul><li>Provide guidance, training, and support to the cleaning teams to maintain consistency in service quality.</li><li>Serve as the primary point of contact for cleaning staff to address queries, resolve issues, and clarify standards.</li></ul></li><li><p><strong>Client Relations &amp; Feedback Management:</strong></p><ul><li>Address and resolve client complaints related to cleaning quality.</li><li>Collect and analyze client feedback to continuously improve cleaning processes and customer satisfaction.</li><li>Liaise with clients to understand their expectations and ensure they are met.</li></ul></li><li><p><strong>Documentation &amp; Reporting:</strong></p><ul><li>Maintain comprehensive records of inspections, feedback, and any corrective actions taken.</li><li>Prepare regular quality control reports and present findings to the management team.</li></ul></li><li><p><strong>Compliance &amp; Standards:</strong></p><ul><li>Ensure that all cleaning activities adhere to health and safety standards, as well as company protocols.</li><li>Monitor compliance with cleaning schedules, equipment usage, and cleanliness protocols.</li></ul></li><li><p><strong>Performance Evaluation:</strong></p><ul><li>Evaluate the performance of cleaning teams based on quality control metrics.</li><li>Implement reward and recognition programs to motivate high performance.</li><li>Recommend disciplinary actions or additional training when quality standards are not met.</li></ul></li></ol><hr /><h4><strong>Qualifications &amp; Skills:</strong></h4><ul><li><strong>Experience:</strong> Minimum of 2 years in a cleaning management, quality control, or related role, preferably within the cleaning or hospitality industry.</li><li><strong>Education:</strong> High school diploma or equivalent; certification in cleaning management or quality assurance is a plus.</li><li><strong>Skills:</strong><ul><li>Strong attention to detail and a commitment to high standards.</li><li>Excellent communication and interpersonal skills.</li><li>Proficiency with remote work tools (e.g., video conferencing, digital collaboration platforms).</li><li>Ability to analyze and interpret data related to quality and performance.</li><li>Problem-solving skills and the ability to make decisions under pressure.</li></ul></li></ul><hr /><h4><strong>Key Competencies:</strong></h4><ul><li>Leadership and team management.</li><li>Customer service orientation.</li><li>Analytical thinking and problem-solving.</li><li>Time management and organizational skills.</li><li>Adaptability and a proactive approach.</li></ul><hr /><h4><strong>Additional Requirements:</strong></h4><ul><li>Reliable internet connection and access to a computer or laptop.</li><li>Availability to work flexible hours, including weekends, if needed.</li></ul><p>This role is ideal for a detail-oriented professional with experience in quality management and a passion for maintaining high standards in the cleaning industry.</p>\n												<a tabindex=\"0\">Job Title: On-Site Quality Control Cleaning Manager</a>\n					<strong>Job Type:</strong> Full-Time / Part-Time<p><strong>Location:</strong> Various Property Sites</p><p><strong>Reports To:</strong> Operations Manager / Account Manager</p><hr /><h4><strong>Job Summary:</strong></h4><p>The On-Site Quality Control Cleaning Manager is responsible for maintaining high standards of cleanliness and client satisfaction across multiple properties by conducting in-person inspections, supervising cleaning teams, and ensuring compliance with company policies and procedures. This role involves direct engagement with cleaning staff and clients, providing real-time feedback, and implementing corrective measures as needed. The manager will oversee cleaning operations, address issues promptly, and ensure a clean, safe, and welcoming environment in all serviced properties.</p><hr /><h4><strong>Key Responsibilities:</strong></h4><ol><li><strong>Quality Assurance &amp; On-Site Inspections:</strong><ul><li>Conduct regular and surprise inspections of properties to evaluate cleaning quality and adherence to company standards.</li><li>Inspect key areas such as high-touch surfaces, restrooms, kitchens, and common areas to ensure thoroughness.</li><li>Identify any cleaning deficiencies and implement corrective actions immediately.</li></ul></li><li><strong>Supervision &amp; Team Management:</strong><ul><li>Supervise cleaning teams on-site, provide support and guidance, and ensure compliance with cleaning schedules and protocols.</li><li>Train new cleaning staff on quality standards, equipment usage, and cleaning techniques.</li><li>Monitor staff performance, provide feedback, and recommend additional training as necessary.</li></ul></li><li><strong>Client Relations &amp; Communication:</strong><ul><li>Serve as the primary point of contact for clients during on-site visits, addressing concerns and ensuring satisfaction.</li><li>Communicate effectively with clients to understand their specific cleaning requirements and preferences.</li><li>Resolve client complaints swiftly and document outcomes.</li></ul></li><li><strong>Health, Safety, &amp; Compliance:</strong><ul><li>Ensure all cleaning operations comply with health, safety, and environmental regulations.</li><li>Verify that cleaning equipment is in good working order and that staff use appropriate personal protective equipment (PPE).</li><li>Conduct safety audits and participate in training programs to maintain a safe working environment.</li></ul></li><li><strong>Documentation &amp; Reporting:</strong><ul><li>Maintain accurate records of inspections, client feedback, corrective actions, and inventory of cleaning supplies.</li><li>Prepare regular reports on cleaning performance and present findings to management.</li><li>Document incidents, accidents, or issues related to cleaning operations.</li></ul></li><li><strong>Inventory &amp; Supplies Management:</strong><ul><li>Monitor the usage and inventory of cleaning supplies and equipment.</li><li>Coordinate with the procurement team to ensure availability of necessary materials.</li><li>Evaluate the need for new cleaning tools or products and make recommendations accordingly.</li></ul></li><li><strong>Performance Evaluation &amp; Improvement:</strong><ul><li>Evaluate the effectiveness of cleaning processes and recommend improvements to optimize quality and efficiency.</li><li>Develop and implement quality control checklists and guidelines for staff to follow.</li><li>Recognize and reward staff for excellent performance and address underperformance through coaching or disciplinary actions.</li></ul></li></ol><hr /><h4><strong>Qualifications &amp; Skills:</strong></h4><ul><li><strong>Experience:</strong> Minimum of 3 years in a cleaning management or quality control role, with hands-on experience in a similar industry.</li><li><strong>Education:</strong> High school diploma or equivalent; advanced training or certifications in cleaning management or quality assurance is a plus.</li><li><strong>Skills:</strong><ul><li>Strong leadership and team management abilities.</li><li>Keen eye for detail and a high standard of cleanliness.</li><li>Excellent verbal and written communication skills.</li><li>Proficiency in using inspection tools and technology to document findings.</li><li>Ability to multitask and manage multiple properties simultaneously.</li><li>Problem-solving skills and the ability to implement solutions on-site.</li></ul></li></ul><hr /><h4><strong>Key Competencies:</strong></h4><ul><li>Leadership and decision-making.</li><li>Customer service orientation.</li><li>Organizational and time management.</li><li>Analytical thinking and problem-solving.</li><li>Adaptability and hands-on approach.</li></ul><a href=\"https://example-site.com/recruitment/\" target=\"_blank\" rel=\"noopener\">Apply Now</a>\n												<a tabindex=\"0\">Operations Agent</a>\n					<h3>Job Description: <strong>Operations Agent</strong></h3><p><strong>Position:</strong> <strong>Operations Agent</strong> <br /><strong>Type:</strong> Gig-based<br /><strong>Reporting To:</strong> Operations Manager</p><h4><strong>Responsibilities:</strong></h4><ol><li>Manage and finalize assigned tasks within the specified budget, including:<ul><li>Following up on maintenance cases.</li><li>Overseeing cleaning tasks and ensuring completion.</li></ul></li><li>Coordinate with relevant teams or service providers to ensure task execution.</li><li>Monitor progress and update stakeholders on task status.</li><li>Resolve any issues or bottlenecks during task completion.</li><li>Ensure quality standards are met for each task.</li><li>Maintain accurate records of task expenses and reports.</li></ol><h4><strong>Requirements:</strong></h4><ul><li>Strong organizational and time-management skills.</li><li>Excellent communication and coordination abilities.</li><li>Prior experience in operations, maintenance, or cleaning task management is a plus.</li><li>Proficiency in tools like Google Sheets and communication apps (e.g., Telegram).</li><li>Ability to work independently and meet deadlines.</li></ul><hr /><h3>Payment Structure:</h3><ol><li><p><strong>Base Rate per Gig:</strong><br />Each task has a predetermined budget. A flat fee or percentage of the budget is allocated to the Task Finalizer (e.g., 10-15% of the task&#8217;s budget or a fixed amount like 2000 EGP per task).</p></li><li><p><strong>Bonuses:</strong></p><ul><li>Early completion of tasks (e.g., 5% bonus for tasks completed ahead of schedule).</li><li>High client satisfaction ratings or exceptional quality.</li><li>Acceptance of tasks, the more tasks are accepted the higher the markup profit will be.</li></ul></li><li><p><strong>Deductions:</strong></p><ul><li>Failure to meet deadlines or budgets.</li><li>Poor quality resulting in additional follow-up tasks.</li></ul></li></ol><hr /><h3>Key Performance Indicators (KPIs):</h3><ol><li><strong>Task Completion Rate:</strong> Percentage of tasks finalized within the assigned budget and deadline.</li><li><strong>Quality Score:</strong> Based on client feedback or internal reviews of completed tasks.</li><li><strong>Communication Effectiveness:</strong> Responsiveness and clarity in updates to stakeholders.</li><li><strong>Efficiency:</strong> Average time taken to finalize a task.</li><li><strong>Budget Adherence:</strong> Percentage of tasks completed without exceeding the assigned budget.</li></ol>','Careers','','publish','closed','closed','','careers','','','2025-03-15 04:37:54','2025-03-15 02:37:54','',0,'https://example-site.com/?page_id=2259',0,'page','',0),(2276,1,'2023-11-03 17:20:38','2023-11-03 17:20:38','{\"event\":[\"create\"],\"success_action\":\"message\",\"success_msg\":\"Thank you for submitting the Recruiting Intake Form. Your application has been received. We will review your submission and get in touch if further information is required. If you have any questions or updates, please don\'t hesitate to contact us.\",\"success_u