g: border-box;\n  font-family: inherit;\n}\n.pm-login-container {\n  width: 100%;\n  max-width: 480px;\n  margin: 0 auto;\n  background-color: #fff;\n  border-radius: 8px;\n  box-shadow: 0 4px 16px rgba(0,0,0,0.1);\n  overflow: hidden;\n}\n.pm-login-form {\n  padding: 30px;\n}\n.pm-form-header {\n  text-align: center;\n  margin-bottom: 30px;\n}\n.pm-logo {\n  width: 80px;\n  height: 80px;\n  margin: 0 auto 20px;\n  background-color: #f5f5f5;\n  border-radius: 8px;\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  box-shadow: 0 2px 6px rgba(0,0,0,0.1);\n}\n.pm-logo span {\n  font-weight: bold;\n  color: #2c3e50;\n}\n.pm-form-header h2 {\n  color: #2c3e50;\n  font-size: 24px;\n  margin: 0 0 10px;\n}\n.pm-form-header p {\n  color: #7f8c8d;\n  margin: 0;\n}\n.pm-form-group {\n  margin-bottom: 20px;\n}\n.pm-form-group label {\n  display: block;\n  margin-bottom: 8px;\n  color: #2c3e50;\n  font-weight: 500;\n}\n.pm-input-container {\n  position: relative;\n}\n.pm-input-container input {\n  width: 100%;\n  padding: 12px 15px;\n  border: 1px solid #ddd;\n  border-radius: 6px;\n  font-size: 14px;\n  transition: all 0.3s;\n}\n.pm-input-container input:focus {\n  border-color: #3498db;\n  box-shadow: 0 0 0 2px rgba(52, 152, 219, 0.2);\n  outline: none;\n}\n.pm-input-icon {\n  position: absolute;\n  right: 15px;\n  top: 50%;\n  transform: translateY(-50%);\n  color: #bdc3c7;\n}\n.pm-remember-support {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  margin-bottom: 25px;\n}\n.pm-remember-me {\n  display: flex;\n  align-items: center;\n}\n.pm-remember-me input {\n  margin-right: 8px;\n}\n.pm-support-link a {\n  color: #3498db;\n  text-decoration: none;\n  font-size: 14px;\n  display: flex;\n  align-items: center;\n}\n.pm-support-link a:before {\n  content: \"💬\";\n  margin-right: 5px;\n}\n.pm-login-button-container {\n  display: flex;\n  justify-content: center;\n  margin-bottom: 20px;\n}\n.pm-login-button {\n  background-colo